import{_ as t,o as i,c as a,ax as s}from"./chunks/framework.Bnt0oLax.js";const p=JSON.parse('{"title":"Writing Defensive Scripts and Includes","description":"Write custom scripts and header/footer includes that survive platform updates — load safely, fail gracefully, and avoid collisions with platform code","frontmatter":{"description":"Write custom scripts and header/footer includes that survive platform updates — load safely, fail gracefully, and avoid collisions with platform code"},"headers":[],"relativePath":"custom-widgets/v2/defensive-scripts-and-includes.md","filePath":"custom-widgets/v2/defensive-scripts-and-includes.md"}'),r={name:"custom-widgets/v2/defensive-scripts-and-includes.md"};function o(n,e,d,l,c,u){return i(),a("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/defensive-scripts-and-includes.md for this page in Markdown format</div><h1 id="writing-defensive-scripts-and-includes" tabindex="-1">Writing Defensive Scripts and Includes <a class="header-anchor" href="#writing-defensive-scripts-and-includes" aria-label="Permalink to &quot;Writing Defensive Scripts and Includes&quot;">​</a></h1><p>Custom scripts and SSI header/footer includes run on every matching page, so they must be written defensively to avoid blocking rendering, breaking the page, or colliding with platform code. Use this guide when you add a global script or a header/footer include.</p><h2 id="defensive-scripting-practices" tabindex="-1">Defensive Scripting Practices <a class="header-anchor" href="#defensive-scripting-practices" aria-label="Permalink to &quot;Defensive Scripting Practices&quot;">​</a></h2><ul><li>Load scripts asynchronously (<code>async</code> or <code>defer</code>) to avoid blocking page rendering.</li><li>Wrap script logic in try/catch blocks so failures are silent rather than breaking the page.</li><li>Never assume specific DOM elements exist — check before acting.</li><li>Scope all selectors and variables to avoid collisions with platform code.</li></ul><h2 id="header-and-footer-includes" tabindex="-1">Header and Footer Includes <a class="header-anchor" href="#header-and-footer-includes" aria-label="Permalink to &quot;Header and Footer Includes&quot;">​</a></h2><p>SSI header and footer includes must stay isolated from platform internals:</p><ul><li><strong>Keep it isolated.</strong> Header and footer sections should not contain scripts that reach into the main page content. Wrap custom content in dedicated container elements and scope all styling to those containers.</li><li><strong>Plan for failure.</strong> If the include fails to load, the community should still function normally. Design your header and footer so the page degrades gracefully without them.</li><li><strong>Review external resources.</strong> If your header or footer loads scripts, fonts, or stylesheets from third-party domains, confirm those sources are trusted and necessary.</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./scripts.html">Script Definition Reference</a> — every field and option for global scripts</li><li><a href="./stylesheets.html">Stylesheet Definition Reference</a> — every field and option for global stylesheets</li><li><a href="./customization-guardrails.html">Customization Guardrails</a> — why these practices matter and which customization approaches are safe</li></ul>',10)])])}const h=t(r,[["render",o]]);export{p as __pageData,h as default};
